package local.snapexplorer.mobile;

import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.provider.DocumentsContract;import android.view.*;import android.widget.*;import android.graphics.Color;import java.io.*;import java.util.concurrent.*;

/** Saves only to an explicit document-picker destination; never shares implicitly. */
public final class ExportActivity extends Activity {
 private static final int SAVE=82;private final ExecutorService worker=Executors.newSingleThreadExecutor();private ChatRepository repository;private String pendingFormat,chat,title;private TextView status;private boolean busy,destroyed;
 private AppStyle style;
 private final String[] formats={"txt","json","html","pdf","media-pdf","memories-pdf","stats-pdf","csv","xlsx","ods","zip"};
 @Override public void onCreate(Bundle state){AppStyle.apply(this);super.onCreate(state);AppStyle.systemBars(this);style=new AppStyle(this);repository=new ChatRepository(getApplicationContext());chat=getIntent().getStringExtra("chat");title=getIntent().getStringExtra("title");if(state!=null)pendingFormat=state.getString("format");
  LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(24,24,24,24);root.setBackgroundColor(style.background);setContentView(root);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(24,24+i.getSystemWindowInsetTop(),24,24+i.getSystemWindowInsetBottom());return i;});
  TextView heading=text("Export locally",26);root.addView(heading);status=text(chat==null?"Choose what to save. The app never sends it anywhere.":"Conversation: "+(title==null?chat:title),14);root.addView(status);
  ScrollView scroll=new ScrollView(this);LinearLayout choices=new LinearLayout(this);choices.setOrientation(1);scroll.addView(choices);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  String[] labels={"Conversation / all chats · Plain text","Conversation / all chats · JSON","Conversation / all chats · Offline HTML","Conversation / all chats · PDF with media previews","Media gallery · PDF","Memories · PDF","Statistics and charts · PDF","Statistics · CSV","Statistics · Excel XLSX","Statistics · OpenDocument ODS","Full portable archive · ZIP"};
  for(int i=0;i<formats.length;i++){final String format=formats[i];Button b=new Button(this);b.setAllCaps(false);b.setText(labels[i]);b.setMinHeight(60);b.setOnClickListener(v->choose(format));choices.addView(b);}
  TextView note=text("Exports contain private data and are not encrypted. Choose an on-device folder for offline storage. ZIP includes original archives, raw metadata, local media and a SHA-256 manifest. Media codecs and PDF fonts depend on the device.",13);root.addView(note);Button back=new Button(this);back.setText("Back");back.setOnClickListener(v->onBackPressed());root.addView(back);
 }
 private TextView text(String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(style.ink);t.setPadding(0,12,0,16);return t;}
 private void choose(String format){if(busy)return;pendingFormat=format;Intent save=new Intent(Intent.ACTION_CREATE_DOCUMENT);save.addCategory(Intent.CATEGORY_OPENABLE);save.setType(mime(format));save.putExtra(Intent.EXTRA_TITLE,"snap-explorer-"+(format.equals("zip")?"archive":format.equals("csv")||format.equals("xlsx")||format.equals("ods")?"statistics":"chats")+"."+(format.endsWith("pdf")?"pdf":format));save.putExtra(Intent.EXTRA_LOCAL_ONLY,true);startActivityForResult(save,SAVE);}
 private String mime(String f){switch(f){case"json":return"application/json";case"html":return"text/html";case"pdf":case"media-pdf":case"memories-pdf":case"stats-pdf":return"application/pdf";case"csv":return"text/csv";case"xlsx":return"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";case"ods":return"application/vnd.oasis.opendocument.spreadsheet";case"zip":return"application/zip";default:return"text/plain";}}
 @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putString("format",pendingFormat);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=SAVE||result!=RESULT_OK||data==null||data.getData()==null||pendingFormat==null)return;Uri destination=data.getData();String format=pendingFormat;busy=true;status.setText("Saving "+format.toUpperCase()+" on this device… Keep this screen open.");
  worker.execute(()->{try(OutputStream output=getContentResolver().openOutputStream(destination,"w")){if(output==null)throw new IOException("The output file could not be opened.");ArchiveExporter.write(this,repository.getReadableDatabase(),output,format,chat,title);runOnUiThread(()->{if(!destroyed){busy=false;status.setText("Saved successfully. Your imported archive is unchanged.");}});}catch(Exception error){try{DocumentsContract.deleteDocument(getContentResolver(),destination);}catch(Exception ignored){}runOnUiThread(()->{if(!destroyed){busy=false;status.setText("Export did not finish. Try a smaller selection or another local folder.");new AlertDialog.Builder(this).setTitle("Could not save export").setMessage("No imported data was changed. A partially created file may need removing if the document provider did not allow cleanup.").setPositiveButton("OK",null).show();}});}});
 }
 @Override public void onBackPressed(){if(busy)Toast.makeText(this,"Keep this screen open while saving",Toast.LENGTH_SHORT).show();else super.onBackPressed();}
 @Override protected void onDestroy(){destroyed=true;worker.shutdownNow();new Thread(()->{try{worker.awaitTermination(30,TimeUnit.SECONDS);}catch(InterruptedException ignored){}if(worker.isTerminated())repository.close();}).start();super.onDestroy();}
}
